"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3251],{55007:e=>{e.exports=JSON.parse('{"functions":[{"name":"step","desc":"Spends the frame\'s remaining budget across every live job.\\n\\nWalls come first across *all* jobs, then prefab detail across all jobs. A\\nchunk with bare walls is navigable; a chunk with props and no walls is a\\nplayer falling through the world, so walls win the budget every time.\\n\\nPrefabs are only *queued* here. The `clone` system copies them node by node\\nand a placement lands in the world from its own completion callback some\\nframes later \u2014 which is also why the queue must be drained by that separate\\nsystem and not from here, since this function returns early once no jobs\\nremain.\\n\\nJobs whose chunk has already been detached are dropped up front, before any\\nbudget is spent. The loops below consume from the end of the list, so a dead\\njob sitting earlier would survive every frame the budget ran out on \u2014 one was\\nobserved lingering for seconds after its chunk unloaded.\\n\\nAlways builds at least one thing per call, so an exhausted budget slows the\\nworld filling in rather than freezing it.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"playerChunks","desc":"Observer positions in chunk space.","lua_type":"{ { x: number, y: number } }"},{"name":"deadline","desc":"`os.clock()` value to stop at.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":63,"path":"src/main/server/utils/builder.luau"}},{"name":"buildNearestWall","desc":"Builds the job\'s nearest remaining wall, re-ordering first if the\\nobservers have moved since this job was last ordered.\\n\\nOrdering once at chunk creation is not enough: a player walking across an\\nalready-created chunk would keep getting walls filled in behind them, and\\na chunk generated while nobody is tracked yet has no positions to sort\\nagainst at all.\\n\\n\\t","params":[{"name":"job","desc":"Mutated: loses the wall it just built.","lua_type":"BuildJob"}],"returns":[],"function_type":"static","private":true,"source":{"line":115,"path":"src/main/server/utils/builder.luau"}},{"name":"build","desc":"Creates a chunk\'s folder and floor, and queues its walls for incremental\\nbuilding.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"},{"name":"runs","desc":"Merged wall runs. Ordering happens in [builder.step], not here.","lua_type":"{ Run }"}],"returns":[{"desc":"The new chunk folder.","lua_type":"Folder"}],"function_type":"static","source":{"line":174,"path":"src/main/server/utils/builder.luau"}},{"name":"addDetail","desc":"Ensures a detail block\'s prefabs exist, building them if this is the first\\ntime the block has come into range.\\n\\nVisibility is not this function\'s job. Once the models exist, `show` and\\n`hide` parent them in and out as `Render` changes \u2014 a block that has been\\nbuilt before needs nothing here at all.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"chunkEntity","desc":"","lua_type":"Entity"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"},{"name":"blockKey","desc":"Detail block key.","lua_type":"number"},{"name":"placements","desc":"The block\'s prefabs.","lua_type":"{ Placement }"},{"name":"placementEntities","desc":"Entity per placement, index-aligned.","lua_type":"{ Entity }"}],"returns":[],"function_type":"static","source":{"line":221,"path":"src/main/server/utils/builder.luau"}},{"name":"placementPartCost","desc":"How many parts a placement\'s prefab would add.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"item","desc":"","lua_type":"Placement"}],"returns":[{"desc":"0 if the prefab is missing.","lua_type":"number"}],"function_type":"static","source":{"line":272,"path":"src/main/server/utils/builder.luau"}}],"properties":[],"types":[],"name":"builder","desc":"The build loop, and the two ways work enters it.\\n\\nThis module only orders and drives work \u2014 the pieces live elsewhere: `walls`\\nmakes geometry, `prefab` reads sources, `placement` builds one prefab,\\n`jobs` holds the work item, `demolition` tears down.\\n\\nVisibility is not handled here either. A placement\'s model is built once and\\nhanded to its entity; the `show` and `hide` systems parent it in and out as\\n`Render` changes.","tags":["server-util"],"realm":["Server"],"source":{"line":16,"path":"src/main/server/utils/builder.luau"}}')}}]);